<script lang="ts">
  import RunnerReference from '@/pages/competitive/RunnerReference.svelte';
  import {runningStyleName} from '@/lib/race/race-display';
  import {RUNNING_STYLES} from './trainee';
  import {simulatorResults,simulatorFinishDistributions,simulatorMatchups,simulatorTeamResults} from './simulator-results';
  import {runnerColor,reportNumber as n} from './simulation-report';
  import type {MonteCarloResult} from './simulator-repository';
  import type {SimulatorUma} from './simulator-uma';
  let {result,umas,selected,metrics,onselect}:{result:MonteCarloResult;umas:SimulatorUma[];selected:number[];metrics:ReturnType<typeof simulatorResults>;onselect:(source:number)=>void}=$props();
  const distribution=$derived(simulatorFinishDistributions(result,umas.length));
  const exhausted=(source:number)=>{const rows=result.report?.runners.find(r=>r.source_input_index===source)?.diagnostics;return rows?rows.filter(d=>d.exhausted_at).length/result.runs*100:undefined;};
  let detailsOpen=$state(false);
  const pairs=$derived(detailsOpen?simulatorMatchups(result,umas.length):[]);
  const teams=$derived(simulatorTeamResults(result,umas));
</script>
<div class="outcome-head"><span>Runner</span><span>Win rate</span><span>Full spurt</span><span>Ran out of HP</span><span>Mean time</span><span>Finish time · shared scale</span></div>
{#each metrics as row}
  {@const spread=distribution.runners.find(r=>r.source===row.source)!}
  <div class="outcome-row" class:highlighted={selected.includes(row.source)} style:--runner-color={runnerColor(row.source)}>
    <button class="runner-pick" aria-pressed={selected.includes(row.source)} onclick={()=>onselect(row.source)}><i aria-hidden="true">{selected.includes(row.source)?'✓':''}</i><RunnerReference name={umas[row.source]!.name} cardId={umas[row.source]!.cardId} detail={'#'+(row.source+1)+' · '+runningStyleName(RUNNING_STYLES.findIndex(style=>style===umas[row.source]!.trainee.runningStyle)+1)} compact/></button>
    <div data-label="Win rate"><strong>{n(row.winRate,1)}%</strong><small title="Wilson 95% interval">{n(row.interval[0],1)}–{n(row.interval[1],1)}%</small></div>
    <div data-label="Full spurt">{row.fullSpurt==null?'—':n(row.fullSpurt,1)+'%'}</div><div data-label="Ran out of HP">{exhausted(row.source)==null?'—':n(exhausted(row.source),1)+'%'}</div><div data-label="Mean time"><strong>{n(row.time,3)} s</strong><small>Median {n(row.timeSummary?.median,3)}</small></div>
    <div class="finish-spread" data-label="Finish distribution"><svg viewBox="0 0 200 38" role="img" aria-label={'Mean '+n(spread.mean,3)+' s, median '+n(spread.median,3)+' s, middle 80% '+n(spread.p10,3)+'–'+n(spread.p90,3)+' s'}><title>{n(spread.min,3)}–{n(spread.max,3)} s · {spread.count} races</title>{#each spread.bins as bin,i}<rect x={i*200/spread.bins.length} y={26-bin/distribution.peak*22} width={200/spread.bins.length-1} height={bin/distribution.peak*22} fill="var(--runner-color)" opacity=".3"/>{/each}<line x1={(spread.p10-distribution.min)/(distribution.max-distribution.min)*200} x2={(spread.p90-distribution.min)/(distribution.max-distribution.min)*200} y1="29" y2="29" stroke="var(--runner-color)" stroke-width="3"/><line x1={(spread.median-distribution.min)/(distribution.max-distribution.min)*200} x2={(spread.median-distribution.min)/(distribution.max-distribution.min)*200} y1="23" y2="35" stroke="var(--text-primary)"/><circle cx={(spread.mean-distribution.min)/(distribution.max-distribution.min)*200} cy="29" r="3" fill="var(--runner-color)"/></svg></div>
  </div>
{/each}
<div class="distribution-key"><span>● Mean · │ Median · ━ Middle 80% · bars: all finishes</span><span>{n(distribution.min,2)}–{n(distribution.max,2)} s · faster ←</span></div>
<details bind:open={detailsOpen}><summary>Placements, consistency and paired comparisons</summary><div class="detail-scroll"><table><thead><tr><th>Runner</th><th>Top 3</th><th>Average place</th><th>Fastest finish</th><th>95% win-rate interval</th></tr></thead><tbody>{#each metrics as row}<tr><th>{umas[row.source]!.name}</th><td>{n(row.top3,1)}%</td><td>{n(row.place)}</td><td>{n(row.best,3)} s</td><td>{row.interval.map(v=>n(v,1)).join('–')}%</td></tr>{/each}</tbody></table></div><div class="detail-scroll"><table><thead><tr><th>Runner</th>{#each umas as _,i}<th>#{i+1} place</th>{/each}</tr></thead><tbody>{#each metrics as row}<tr><th>{umas[row.source]!.name}</th>{#each row.finishes as count}<td>{count} <small>({n(count/result.runs*100,1)}%)</small></td>{/each}</tr>{/each}</tbody></table></div><h3>Finishes ahead in the same race</h3><div class="detail-scroll"><table><thead><tr><th>Runner</th>{#each metrics as row}<th>#{row.source+1}</th>{/each}</tr></thead><tbody>{#each metrics as row}<tr><th>#{row.source+1} {umas[row.source]!.name}</th>{#each metrics as other}{@const pair=pairs[row.source]?.[other.source]}<td title={pair?'95% interval '+n(pair.interval[0],1)+'–'+n(pair.interval[1],1)+'%; mean finish-time delta '+n(pair.gap,3)+' s':''}>{pair?n(pair.rate,1)+'%':'—'}</td>{/each}</tr>{/each}</tbody></table></div><p class="report-note">Win-rate intervals are Wilson 95% intervals. Quantiles describe observed finishes. Every pairing uses runners from the same race; overlapping intervals alone are not a test of the difference.</p></details>
{#if teams.length}<details><summary>Optional team outcomes</summary><div class="team-outcomes">{#each teams as team}<div><i style:background={umas[team.sources[0]!]!.teamColor??'#777'}></i><strong>{n(team.winRate,1)}% wins</strong><span>{team.sources.map(s=>umas[s]!.name).join(', ')}</span><small>95% interval {n(team.interval[0],1)}–{n(team.interval[1],1)}%</small></div>{/each}</div></details>{/if}
<style>
  .outcome-head,.outcome-row{display:grid;grid-template-columns:minmax(180px,1.3fr) .65fr .5fr .6fr .8fr minmax(170px,1.4fr);gap:12px;align-items:center}.outcome-head{font-size:10px;color:var(--text-secondary);padding-bottom:8px}.outcome-row{border-top:1px solid var(--border-subtle);padding:5px 4px;font-size:12px}.outcome-row>div{display:grid;gap:2px}.outcome-row strong{font-weight:600}.outcome-row small{font-size:10px;color:var(--text-secondary)}.highlighted{background:color-mix(in srgb,var(--runner-color) 4%,transparent)}.runner-pick{display:flex;align-items:center;gap:8px;background:transparent;border:0;color:inherit;padding:0;font:inherit;text-align:left;cursor:pointer;min-width:0;min-height:36px}.runner-pick i{display:grid;place-items:center;flex:0 0 14px;width:14px;height:14px;border:1px solid var(--runner-color);border-radius:3px;font-style:normal;font-size:10px;color:var(--runner-color)}.runner-pick:focus-visible{outline:2px solid var(--accent-primary);outline-offset:2px}.finish-spread svg{width:100%;height:34px;display:block}.distribution-key{display:flex;gap:8px;flex-wrap:wrap;justify-content:space-between;font-size:10px;color:var(--text-secondary);padding:8px 0}.team-outcomes{display:grid;gap:8px;padding-top:8px}.team-outcomes>div{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.team-outcomes i{width:12px;height:12px;border-radius:3px}.team-outcomes span,.team-outcomes small{color:var(--text-secondary)}
  @media(max-width:900px){.outcome-head,.outcome-row{grid-template-columns:minmax(170px,1.3fr) .65fr .5fr .6fr .8fr}.outcome-head>span:last-child{display:none}.finish-spread{grid-column:2/-1}.finish-spread svg{height:24px}.outcome-row{row-gap:0}}
  @media(max-width:600px){.outcome-head{display:none}.outcome-row{grid-template-columns:repeat(4,minmax(0,1fr));gap:6px 8px;padding:8px 0}.outcome-row>.runner-pick{grid-column:1/-1}.outcome-row>[data-label]:before{content:attr(data-label);font-size:9px;color:var(--text-secondary);display:block}.outcome-row>.finish-spread{grid-column:1/-1}.outcome-row>.finish-spread:before{display:none}.finish-spread svg{height:24px}.outcome-row small{font-size:9px}.outcome-row strong{white-space:nowrap}.distribution-key{line-height:1.6}}
</style>

